module tb;
    // Declare inputs as regs, outputs as wires
    reg [7:0] a;
    reg [7:0] b;
    wire [7:0] s;
    wire overflow;

    // Instantiate TopModule dut
    TopModule dut (
        .a(a),
        .b(b),
        .s(s),
        .overflow(overflow)
    );

    integer errors = 0;

    // Task to check outputs against expected values
    task check_results;
        input [7:0] exp_s;
        input exp_ovf;
        begin
            #1; // Allow propagation delay
            if (s !== exp_s || overflow !== exp_ovf) begin
                errors = errors + 1;
                $display("Mismatch: a=%d, b=%d | Got s=%d (hex:%h), overflow=%b | Expected s=%d (hex:%h), overflow=%b",
                         $signed(a), $signed(b), s, s, overflow, exp_s, exp_s, exp_ovf);
            end
        end
    endtask

    // Behavioral model for 8-bit signed addition and overflow detection
    function [8:0] expected_add;
        input [7:0] op1;
        input [7:0] op2;
        reg [8:0] sum_full;
        reg [7:0] sum_trunc;
        reg ovf;
        begin
            sum_full = {op1[7], op1} + {op2[7], op2};
            sum_trunc = op1 + op2;
            // Signed overflow occurs when two numbers of the same sign are added 
            // and the result has a different sign.
            ovf = (op1[7] == op2[7]) && (sum_trunc[7] != op1[7]);
            expected_add = {ovf, sum_trunc};
        end
    endfunction

    reg [8:0] exp;
    integer i, j;

    initial begin
        // Test vector 1: Basic positive + positive (no overflow)
        a = 8'd10; b = 8'd20;
        exp = expected_add(a, b);
        check_results(exp[7:0], exp[8]);

        // Test vector 2: Positive + positive with overflow
        a = 8'd100; b = 8'd50;
        exp = expected_add(a, b);
        check_results(exp[7:0], exp[8]);

        // Test vector 3: Negative + negative (no overflow)
        a = -8'd10; b = -8'd20;
        exp = expected_add(a, b);
        check_results(exp[7:0], exp[8]);

        // Test vector 4: Negative + negative with overflow
        a = -8'd100; b = -8'd50;
        exp = expected_add(a, b);
        check_results(exp[7:0], exp[8]);

        // Test vector 5: Positive + negative (never overflows)
        a = 8'd50; b = -8'd20;
        exp = expected_add(a, b);
        check_results(exp[7:0], exp[8]);

        // Test vector 6: Negative + positive (never overflows)
        a = -8'd50; b = 8'd20;
        exp = expected_add(a, b);
        check_results(exp[7:0], exp[8]);

        // Test vector 7: Zero inputs
        a = 8'd0; b = 8'd0;
        exp = expected_add(a, b);
        check_results(exp[7:0], exp[8]);

        // Test vector 8: Max positive + (-1)
        a = 8'sd127; b = -8'd1;
        exp = expected_add(a, b);
        check_results(exp[7:0], exp[8]);

        // Test vector 9: Min negative + 1
        a = -8'sd128; b = 8'd1;
        exp = expected_add(a, b);
        check_results(exp[7:0], exp[8]);

        // Systematic bounded loop across corner cases and arbitrary samples
        for (i = -128; i <= 127; i = i + 31) begin
            for (j = -128; j <= 127; j = j + 37) begin
                a = i[7:0];
                b = j[7:0];
                exp = expected_add(a, b);
                check_results(exp[7:0], exp[8]);
            end
        end

        // Final result evaluation
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule
